select
    coalesce(t1.dt_month, t2.dt_month) as dt_month,
    coalesce(t1.region, t2.region) as region,
    100 * (t1.gross_margin_ytd - t2.gross_margin_prior_ytd) as margin_change_pp
from #DML_FACT_PROFITABILITY_BY_DM_R_1AF5D05_YTD t1
full outer join #DML_FACT_PROFITABILITY_BY_DM_R_38AAD05_YTD_YA t2
    on t2.dt_month = t1.dt_month
    and t2.region = t1.region
)


